using Dip.Domain.Enums; namespace Dip.Domain.Entities; public sealed class QualityIssue { private QualityIssue(){} public QualityIssue(Guid id,Guid projectId,Guid runId,string category,Severity severity,string title,string description,string? source,DateTimeOffset created){Id=id==Guid.Empty?Guid.NewGuid():id;ProjectId=projectId;PipelineRunId=runId;Category=Req(category,80);Severity=severity;Title=Req(title,200);Description=Req(description,4000);Source=string.IsNullOrWhiteSpace(source)?null:source.Trim();Status=IssueStatus.Open;CreatedAtUtc=created;} public Guid Id{get;private set;} public Guid ProjectId{get;private set;} public Guid PipelineRunId{get;private set;} public string Category{get;private set;}=string.Empty; public Severity Severity{get;private set;} public string Title{get;private set;}=string.Empty; public string Description{get;private set;}=string.Empty; public string? Source{get;private set;} public IssueStatus Status{get;private set;} public DateTimeOffset CreatedAtUtc{get;private set;} public DateTimeOffset? ResolvedAtUtc{get;private set;} public void Resolve(DateTimeOffset at){Status=IssueStatus.Resolved;ResolvedAtUtc=at;} private static string Req(string v,int max){v=v?.Trim()??string.Empty;if(v.Length<1||v.Length>max) throw new ArgumentException("Invalid issue text.");return v;} }